  assign ctrl_start_we = addr_hit[0] & reg_we & !reg_error;
  assign ctrl_start_wd = reg_wdata[0];

  assign ctrl_clr_we = addr_hit[0] & reg_we & !reg_error;
  assign ctrl_clr_wd = reg_wdata[1];

  assign ctrl_clr_param_we = addr_hit[0] & reg_we & !reg_error;
  assign ctrl_clr_param_wd = reg_wdata[2];

  assign ctrl_clr_conf_we = addr_hit[0] & reg_we & !reg_error;
  assign ctrl_clr_conf_wd = reg_wdata[3];

  assign ctrl_clr_perf_ctr_we = addr_hit[0] & reg_we & !reg_error;
  assign ctrl_clr_perf_ctr_wd = reg_wdata[4];

  assign mode_intr_en_we = addr_hit[1] & reg_we & !reg_error;
  assign mode_intr_en_wd = reg_wdata[0];

  assign mode_perf_ctr_en_we = addr_hit[1] & reg_we & !reg_error;
  assign mode_perf_ctr_en_wd = reg_wdata[1];

  assign conf_addr_we = addr_hit[7] & reg_we & !reg_error;
  assign conf_addr_wd = reg_wdata[31:0];

  assign ise_sew_ise_0_sew_we = addr_hit[8] & reg_we & !reg_error;
  assign ise_sew_ise_0_sew_wd = reg_wdata[2:0];

  assign ise_sew_ise_1_sew_we = addr_hit[8] & reg_we & !reg_error;
  assign ise_sew_ise_1_sew_wd = reg_wdata[5:3];

  assign ise_sew_ise_2_sew_we = addr_hit[8] & reg_we & !reg_error;
  assign ise_sew_ise_2_sew_wd = reg_wdata[8:6];

  assign ise_sew_ise_3_sew_we = addr_hit[8] & reg_we & !reg_error;
  assign ise_sew_ise_3_sew_wd = reg_wdata[11:9];

  assign ose_sew_ose_0_sew_we = addr_hit[9] & reg_we & !reg_error;
  assign ose_sew_ose_0_sew_wd = reg_wdata[2:0];

  assign ose_sew_ose_1_sew_we = addr_hit[9] & reg_we & !reg_error;
  assign ose_sew_ose_1_sew_wd = reg_wdata[5:3];

  assign ose_sew_ose_2_sew_we = addr_hit[9] & reg_we & !reg_error;
  assign ose_sew_ose_2_sew_wd = reg_wdata[8:6];

  assign ose_sew_ose_3_sew_we = addr_hit[9] & reg_we & !reg_error;
  assign ose_sew_ose_3_sew_wd = reg_wdata[11:9];

  assign ise_0_addr_we = addr_hit[10] & reg_we & !reg_error;
  assign ise_0_addr_wd = reg_wdata[31:0];

  assign ise_0_param_ise_0_size_we = addr_hit[11] & reg_we & !reg_error;
  assign ise_0_param_ise_0_size_wd = reg_wdata[15:0];

  assign ise_0_param_ise_0_stride_we = addr_hit[11] & reg_we & !reg_error;
  assign ise_0_param_ise_0_stride_wd = reg_wdata[31:16];

  assign ise_1_addr_we = addr_hit[12] & reg_we & !reg_error;
  assign ise_1_addr_wd = reg_wdata[31:0];

  assign ise_1_param_ise_1_size_we = addr_hit[13] & reg_we & !reg_error;
  assign ise_1_param_ise_1_size_wd = reg_wdata[15:0];

  assign ise_1_param_ise_1_stride_we = addr_hit[13] & reg_we & !reg_error;
  assign ise_1_param_ise_1_stride_wd = reg_wdata[31:16];

  assign ise_2_addr_we = addr_hit[14] & reg_we & !reg_error;
  assign ise_2_addr_wd = reg_wdata[31:0];

  assign ise_2_param_ise_2_size_we = addr_hit[15] & reg_we & !reg_error;
  assign ise_2_param_ise_2_size_wd = reg_wdata[15:0];

  assign ise_2_param_ise_2_stride_we = addr_hit[15] & reg_we & !reg_error;
  assign ise_2_param_ise_2_stride_wd = reg_wdata[31:16];

  assign ise_3_addr_we = addr_hit[16] & reg_we & !reg_error;
  assign ise_3_addr_wd = reg_wdata[31:0];

  assign ise_3_param_ise_3_size_we = addr_hit[17] & reg_we & !reg_error;
  assign ise_3_param_ise_3_size_wd = reg_wdata[15:0];

  assign ise_3_param_ise_3_stride_we = addr_hit[17] & reg_we & !reg_error;
  assign ise_3_param_ise_3_stride_wd = reg_wdata[31:16];

  assign ose_0_addr_we = addr_hit[18] & reg_we & !reg_error;
  assign ose_0_addr_wd = reg_wdata[31:0];

  assign ose_0_param_ose_0_size_we = addr_hit[19] & reg_we & !reg_error;
  assign ose_0_param_ose_0_size_wd = reg_wdata[15:0];

  assign ose_0_param_ose_0_stride_we = addr_hit[19] & reg_we & !reg_error;
  assign ose_0_param_ose_0_stride_wd = reg_wdata[31:16];

  assign ose_1_addr_we = addr_hit[20] & reg_we & !reg_error;
  assign ose_1_addr_wd = reg_wdata[31:0];

  assign ose_1_param_ose_1_size_we = addr_hit[21] & reg_we & !reg_error;
  assign ose_1_param_ose_1_size_wd = reg_wdata[15:0];

  assign ose_1_param_ose_1_stride_we = addr_hit[21] & reg_we & !reg_error;
  assign ose_1_param_ose_1_stride_wd = reg_wdata[31:16];

  assign ose_2_addr_we = addr_hit[22] & reg_we & !reg_error;
  assign ose_2_addr_wd = reg_wdata[31:0];

  assign ose_2_param_ose_2_size_we = addr_hit[23] & reg_we & !reg_error;
  assign ose_2_param_ose_2_size_wd = reg_wdata[15:0];

  assign ose_2_param_ose_2_stride_we = addr_hit[23] & reg_we & !reg_error;
  assign ose_2_param_ose_2_stride_wd = reg_wdata[31:16];

  assign ose_3_addr_we = addr_hit[24] & reg_we & !reg_error;
  assign ose_3_addr_wd = reg_wdata[31:0];

  assign ose_3_param_ose_3_size_we = addr_hit[25] & reg_we & !reg_error;
  assign ose_3_param_ose_3_size_wd = reg_wdata[15:0];

  assign ose_3_param_ose_3_stride_we = addr_hit[25] & reg_we & !reg_error;
  assign ose_3_param_ose_3_stride_wd = reg_wdata[31:16];

  // Read data return
  always_comb begin
    reg_rdata_next = '0;
    unique case (1'b1)
      addr_hit[0]: begin
        reg_rdata_next[0] = '0;
        reg_rdata_next[1] = '0;
        reg_rdata_next[2] = '0;
        reg_rdata_next[3] = '0;
        reg_rdata_next[4] = '0;
      end

      addr_hit[1]: begin
        reg_rdata_next[0] = '0;
        reg_rdata_next[1] = '0;
      end

      addr_hit[2]: begin
        reg_rdata_next[0] = status_exec_done_qs;
        reg_rdata_next[1] = status_conf_done_qs;
      end

      addr_hit[3]: begin
        reg_rdata_next[31:0] = perf_ctr_total_cycles_qs;
      end

      addr_hit[4]: begin
        reg_rdata_next[31:0] = perf_ctr_exec_cycles_qs;
      end

      addr_hit[5]: begin
        reg_rdata_next[31:0] = perf_ctr_conf_cycles_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[31:0] = perf_ctr_stall_cycles_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[31:0] = conf_addr_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[2:0]  = ise_sew_ise_0_sew_qs;
        reg_rdata_next[5:3]  = ise_sew_ise_1_sew_qs;
        reg_rdata_next[8:6]  = ise_sew_ise_2_sew_qs;
        reg_rdata_next[11:9] = ise_sew_ise_3_sew_qs;
      end

      addr_hit[9]: begin
        reg_rdata_next[2:0]  = ose_sew_ose_0_sew_qs;
        reg_rdata_next[5:3]  = ose_sew_ose_1_sew_qs;
        reg_rdata_next[8:6]  = ose_sew_ose_2_sew_qs;
        reg_rdata_next[11:9] = ose_sew_ose_3_sew_qs;
      end

      addr_hit[10]: begin
        reg_rdata_next[31:0] = ise_0_addr_qs;
      end

      addr_hit[11]: begin
        reg_rdata_next[15:0]  = ise_0_param_ise_0_size_qs;
        reg_rdata_next[31:16] = ise_0_param_ise_0_stride_qs;
      end

      addr_hit[12]: begin
        reg_rdata_next[31:0] = ise_1_addr_qs;
      end

      addr_hit[13]: begin
        reg_rdata_next[15:0]  = ise_1_param_ise_1_size_qs;
        reg_rdata_next[31:16] = ise_1_param_ise_1_stride_qs;
      end

      addr_hit[14]: begin
        reg_rdata_next[31:0] = ise_2_addr_qs;
      end

      addr_hit[15]: begin
        reg_rdata_next[15:0]  = ise_2_param_ise_2_size_qs;
        reg_rdata_next[31:16] = ise_2_param_ise_2_stride_qs;
      end

      addr_hit[16]: begin
        reg_rdata_next[31:0] = ise_3_addr_qs;
      end

      addr_hit[17]: begin
        reg_rdata_next[15:0]  = ise_3_param_ise_3_size_qs;
        reg_rdata_next[31:16] = ise_3_param_ise_3_stride_qs;
      end

      addr_hit[18]: begin
        reg_rdata_next[31:0] = ose_0_addr_qs;
      end

      addr_hit[19]: begin
        reg_rdata_next[15:0]  = ose_0_param_ose_0_size_qs;
        reg_rdata_next[31:16] = ose_0_param_ose_0_stride_qs;
      end

      addr_hit[20]: begin
        reg_rdata_next[31:0] = ose_1_addr_qs;
      end

      addr_hit[21]: begin
        reg_rdata_next[15:0]  = ose_1_param_ose_1_size_qs;
        reg_rdata_next[31:16] = ose_1_param_ose_1_stride_qs;
      end

      addr_hit[22]: begin
        reg_rdata_next[31:0] = ose_2_addr_qs;
      end

      addr_hit[23]: begin
        reg_rdata_next[15:0]  = ose_2_param_ose_2_size_qs;
        reg_rdata_next[31:16] = ose_2_param_ose_2_stride_qs;
      end

      addr_hit[24]: begin
        reg_rdata_next[31:0] = ose_3_addr_qs;
      end

      addr_hit[25]: begin
        reg_rdata_next[15:0]  = ose_3_param_ose_3_size_qs;
        reg_rdata_next[31:16] = ose_3_param_ose_3_stride_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule

module strela_reg_top_intf #(
  parameter  int AW = 7,
  localparam int DW = 32
) (
  input logic clk_i,
  input logic rst_ni,
  REG_BUS.in regbus_slave,
  // To HW
  output strela_reg_pkg::strela_reg2hw_t reg2hw,  // Write
  input strela_reg_pkg::strela_hw2reg_t hw2reg,  // Read
  // Config
  input devmode_i  // If 1, explicit error return for unmapped register access
);
  localparam int unsigned STRB_WIDTH = DW / 8;

  `include "register_interface/typedef.svh"
  `include "register_interface/assign.svh"

  // Define structs for reg_bus
  typedef logic [AW-1:0] addr_t;
  typedef logic [DW-1:0] data_t;
  typedef logic [STRB_WIDTH-1:0] strb_t;
  `REG_BUS_TYPEDEF_ALL(reg_bus, addr_t, data_t, strb_t)

  reg_bus_req_t s_reg_req;
  reg_bus_rsp_t s_reg_rsp;

  // Assign SV interface to structs
  `REG_BUS_ASSIGN_TO_REQ(s_reg_req, regbus_slave)
  `REG_BUS_ASSIGN_FROM_RSP(regbus_slave, s_reg_rsp)



  strela_reg_top #(
    .reg_req_t(reg_bus_req_t),
    .reg_rsp_t(reg_bus_rsp_t),
    .AW(AW)
  ) i_regs (
    .clk_i,
    .rst_ni,
    .reg_req_i(s_reg_req),
    .reg_rsp_o(s_reg_rsp),
    .reg2hw,  // Write
    .hw2reg,  // Read
    .devmode_i
  );

endmodule


